import React, { useState, useEffect, useCallback } from "react";
import { AuthProvider } from "./context/AuthContext";
import { RealtimeProvider } from "./context/RealtimeContext";
import { ThemeProvider } from "./context/ThemeContext";
import { Navbar } from "./components/Navbar";
import { Footer } from "./components/Footer";
import { HomePage } from "./pages/HomePage";
import { SearchPage } from "./pages/SearchPage";
import { RestaurantDetailPage } from "./pages/RestaurantDetailPage";
import { ProfilePage } from "./pages/ProfilePage";
import { OwnerDashboardPage } from "./pages/OwnerDashboardPage";
import { AdminDashboardPage } from "./pages/AdminDashboardPage";
import { LoginPage } from "./pages/LoginPage";

// Modals & Widgets
import { BookingModal } from "./components/BookingModal";
import { AIRecommenderModal } from "./components/AIRecommenderModal";
import { CheckInModal } from "./components/CheckInModal";
import { ReviewModal } from "./components/ReviewModal";
import { ComplaintModal } from "./components/ComplaintModal";
import { WaitlistModal } from "./components/WaitlistModal";
import { AIChatWidget } from "./components/AIChatWidget";

import { api } from "./services/api";
import { useAuth } from "./context/AuthContext";
import { useRecentlyViewed } from "./hooks/useRecentlyViewed";

function AppContent() {
  const { registerRoleSwitchHandler } = useAuth();
  const { recentlyViewed, addToRecents } = useRecentlyViewed();

  const [currentView, setCurrentView] = useState("login");
  const [selectedCity, setSelectedCity] = useState("All Cities");
  const [cities, setCities] = useState([]);
  const [cuisines, setCuisines] = useState([]);

  const [selectedRestaurantId, setSelectedRestaurantId] = useState(null);
  const [searchParams, setSearchParams] = useState({});

  // Modals state
  const [activeBookingRest, setActiveBookingRest] = useState(null);
  const [activeBookingPreOrders, setActiveBookingPreOrders] = useState([]);
  const [activeWaitlistRest, setActiveWaitlistRest] = useState(null);
  const [activeComplaintRest, setActiveComplaintRest] = useState(null);
  const [activeReviewBooking, setActiveReviewBooking] = useState(null);
  const [showAIModal, setShowAIModal] = useState(false);
  const [aiInitialPrompt, setAiInitialPrompt] = useState("");
  const [showCheckInModal, setShowCheckInModal] = useState(false);

  // Centralized Navigation helper that pushes history state for Browser Back/Forward buttons
  const navigateTo = useCallback((view, extraState = {}, replace = false) => {
    setCurrentView(view);
    if (extraState.restaurantId) {
      setSelectedRestaurantId(extraState.restaurantId);
    }
    if (extraState.searchParams) {
      setSearchParams(extraState.searchParams);
    }

    const state = { view, ...extraState };
    const hash = extraState.restaurantId ? `#${view}?id=${extraState.restaurantId}` : `#${view}`;

    if (replace) {
      window.history.replaceState(state, "", hash);
    } else {
      window.history.pushState(state, "", hash);
    }
    window.scrollTo({ top: 0, behavior: "smooth" });
  }, []);

  // Listen to Browser Back / Forward buttons (popstate event)
  useEffect(() => {
    const handlePopState = (event) => {
      if (event.state && event.state.view) {
        setCurrentView(event.state.view);
        if (event.state.restaurantId) {
          setSelectedRestaurantId(event.state.restaurantId);
        }
        if (event.state.searchParams) {
          setSearchParams(event.state.searchParams);
        }
      } else {
        // Handle hash fallbacks or default view
        const hash = window.location.hash.replace("#", "").split("?")[0];
        if (["home", "search", "detail", "profile", "owner", "admin", "login"].includes(hash)) {
          setCurrentView(hash);
        } else {
          setCurrentView("login");
        }
      }
    };

    // Set initial state for root URL if no state exists
    if (!window.history.state) {
      window.history.replaceState({ view: "login" }, "", "#login");
    }

    window.addEventListener("popstate", handlePopState);
    return () => window.removeEventListener("popstate", handlePopState);
  }, []);

  useEffect(() => {
    async function loadMeta() {
      try {
        const [cList, cuList] = await Promise.all([api.getCities(), api.getCuisines()]);
        setCities(cList);
        setCuisines(cuList);
      } catch (err) {
        console.error("Meta load error", err);
      }
    }
    loadMeta();
  }, []);

  const handleSearchTrigger = (params) => {
    setSearchParams(params);
    if (params.city) setSelectedCity(params.city);
    navigateTo("search", { searchParams: params });
  };

  const handleSelectRestaurant = (rest) => {
    setSelectedRestaurantId(rest.id);
    addToRecents(rest);
    navigateTo("detail", { restaurantId: rest.id });
  };

  const handleOpenAI = (prompt = "") => {
    setAiInitialPrompt(prompt);
    setShowAIModal(true);
  };

  // Auto-navigate when user switches demo roles
  const handleRoleSwitch = useCallback((role) => {
    let targetView = "home";
    if (role === "ADMIN") {
      targetView = "admin";
    } else if (role === "RESTAURANT_OWNER") {
      targetView = "owner";
    }
    navigateTo(targetView);
  }, [navigateTo]);

  // Register the handler once on mount
  useEffect(() => {
    registerRoleSwitchHandler(handleRoleSwitch);
  }, [registerRoleSwitchHandler, handleRoleSwitch]);

  return (
    <div className="app-container">
      {/* Top Navigation (Hidden on Login Page) */}
      {currentView !== "login" && (
        <Navbar
          onNavigate={(view) => navigateTo(view)}
          currentView={currentView}
          selectedCity={selectedCity}
          onSelectCity={(city) => {
            setSelectedCity(city);
            handleSearchTrigger({ city: city === "All Cities" ? "" : city });
          }}
          onOpenAI={() => handleOpenAI()}
        />
      )}

      {/* Main Routed Page Content */}
      <main className="main-content">
        {currentView === "home" && (
          <HomePage
            onSearch={handleSearchTrigger}
            onSelectRestaurant={handleSelectRestaurant}
            onBookRestaurant={(r) => setActiveBookingRest(r)}
            onDirections={handleSelectRestaurant}
            onOpenAI={handleOpenAI}
            cities={cities}
            cuisines={cuisines}
            selectedCity={selectedCity}
            onSelectCity={setSelectedCity}
            recentlyViewed={recentlyViewed}
          />
        )}

        {currentView === "search" && (
          <SearchPage
            initialParams={searchParams}
            onSelectRestaurant={handleSelectRestaurant}
            onBookRestaurant={(r) => setActiveBookingRest(r)}
            onDirections={handleSelectRestaurant}
            onOpenAI={handleOpenAI}
            cities={cities}
            cuisines={cuisines}
          />
        )}

        {currentView === "detail" && selectedRestaurantId && (
          <RestaurantDetailPage
            restaurantId={selectedRestaurantId}
            onBack={() => window.history.back()}
            onBook={(r, preOrders = []) => {
              setActiveBookingRest(r);
              setActiveBookingPreOrders(preOrders);
            }}
            onOpenWaitlist={(r) => setActiveWaitlistRest(r)}
            onOpenFileComplaint={(r) => setActiveComplaintRest(r)}
            onWriteReview={(booking, rest) => setActiveReviewBooking({ booking, rest })}
          />
        )}

        {currentView === "profile" && (
          <ProfilePage
            onSelectRestaurant={handleSelectRestaurant}
            onBookRestaurant={(r) => {
              setActiveBookingRest(r);
              setActiveBookingPreOrders([]);
            }}
            onWriteReview={(booking, rest) => setActiveReviewBooking({ booking, rest })}
            recentlyViewed={recentlyViewed}
          />
        )}

        {currentView === "owner" && <OwnerDashboardPage />}

        {currentView === "admin" && <AdminDashboardPage />}

        {currentView === "login" && (
          <LoginPage
            onNavigate={(view) => navigateTo(view)}
            onLoginSuccess={(role) => {
              if (role === "ADMIN") {
                navigateTo("admin");
              } else if (role === "RESTAURANT_OWNER") {
                navigateTo("owner");
              } else {
                navigateTo("home");
              }
            }}
          />
        )}
      </main>

      {/* Footer (Hidden on Login Page) */}
      {currentView !== "login" && (
        <Footer
          onSelectCity={(city) => {
            setSelectedCity(city);
            handleSearchTrigger({ city });
          }}
          onSelectCuisine={(cuisine) => {
            handleSearchTrigger({ cuisine });
          }}
        />
      )}

      {/* Modals Container */}
      {activeBookingRest && (
        <BookingModal
          restaurant={activeBookingRest}
          preOrders={activeBookingPreOrders}
          onClose={() => {
            setActiveBookingRest(null);
            setActiveBookingPreOrders([]);
          }}
          onBookingSuccess={() => {}}
        />
      )}

      {showAIModal && (
        <AIRecommenderModal
          initialQuery={aiInitialPrompt}
          onClose={() => setShowAIModal(false)}
          onSelectRestaurant={(r) => handleSelectRestaurant(r)}
          onBookRestaurant={(r) => setActiveBookingRest(r)}
        />
      )}

      {showCheckInModal && (
        <CheckInModal
          onClose={() => setShowCheckInModal(false)}
          onCheckInSuccess={() => {}}
        />
      )}

      {activeWaitlistRest && (
        <WaitlistModal
          restaurant={activeWaitlistRest}
          onClose={() => setActiveWaitlistRest(null)}
        />
      )}

      {activeComplaintRest && (
        <ComplaintModal
          restaurant={activeComplaintRest}
          onClose={() => setActiveComplaintRest(null)}
        />
      )}

      {activeReviewBooking && (
        <ReviewModal
          booking={activeReviewBooking.booking}
          restaurant={activeReviewBooking.rest}
          onClose={() => setActiveReviewBooking(null)}
          onReviewSubmitted={() => {
            if (currentView === "detail") {
              // Reload details
            }
          }}
        />
      )}

      {/* Persistent Floating AI Chat Assistant Widget (Hidden on Login Page) */}
      {currentView !== "login" && (
        <AIChatWidget
          onSelectRestaurant={handleSelectRestaurant}
          onBookRestaurant={(r) => setActiveBookingRest(r)}
        />
      )}
    </div>
  );
}

export default function App() {
  return (
    <ThemeProvider>
      <AuthProvider>
        <RealtimeProvider>
          <AppContent />
        </RealtimeProvider>
      </AuthProvider>
    </ThemeProvider>
  );
}

import React, { useState, useRef, useEffect } from "react";
import { 
  Sparkles, Send, X, Bot, User, Star, MapPin, 
  Utensils, ArrowRight, MessageSquare, ShieldCheck, Award, ChevronDown, Minimize2, Store, Shield, Check, Navigation
} from "lucide-react";
import { api } from "../services/api";
import { useAuth } from "../context/AuthContext";

export function AIChatWidget({ onSelectRestaurant, onBookRestaurant }) {
  const { user, isCustomer, isOwner, isAdmin } = useAuth();

  const [isOpen, setIsOpen] = useState(false);
  const [inputMessage, setInputMessage] = useState("");
  const [loading, setLoading] = useState(false);
  const [pendingMutation, setPendingMutation] = useState(null);

  // Role-based Configs (Matching Master Prompt Section 8 Exactly)
  const ROLE_CONFIG = {
    ADMIN: {
      title: "Admin AI Supervisor",
      badge: "Platform Governance",
      gradient: "linear-gradient(135deg, #4C1D95 0%, #6D28D9 100%)",
      icon: Shield,
      welcomeText: "≡ƒ¢í∩╕Å Greetings Administrator! I am your Platform Governance Supervisor. Ask me about system-wide booking volume, verification audit logs, or registered restaurant owners across Tamil Nadu.",
      quickPrompts: [
        "≡ƒîÉ Tamil Nadu Overview",
        "≡ƒôè Platform Statistics",
        "≡ƒ¢í∩╕Å Verification Audit",
        "≡ƒæ¿≡ƒÆ╝ Registered Owners",
        "≡ƒì╜∩╕Å Restaurant Statistics",
        "≡ƒôà Booking Analytics",
        "≡ƒÜ¿ Pending Complaints"
      ]
    },
    RESTAURANT_OWNER: {
      title: "Restaurant Owner AI Assistant",
      badge: "Restaurant Operations",
      gradient: "linear-gradient(135deg, #7C2D12 0%, #D97706 100%)",
      icon: Store,
      welcomeText: "≡ƒÅ¬ Vanakkam Partner! I am your Restaurant Operations Assistant. Ask me about today's bookings, table availability, check-in codes, or operational status updates!",
      quickPrompts: [
        "≡ƒôà Today's Bookings",
        "≡ƒ¬æ Table Availability",
        "Γ£à Today's Check-ins",
        "ΓÅ│ Waiting Time",
        "≡ƒì¢ Menu Availability",
        "≡ƒà┐∩╕Å Parking Status",
        "Γ¡É Reviews",
        "≡ƒÜ¿ Complaints",
        "≡ƒÅå Loyalty Visits",
        "≡ƒôè Restaurant Analytics"
      ]
    },
    CUSTOMER: {
      title: "Customer AI",
      badge: "Customer Recommender",
      gradient: "linear-gradient(135deg, #047857 0%, #10B981 100%)",
      icon: Bot,
      welcomeText: "≡ƒæï Vanakkam! I am your Customer AI Assistant for Tamil Nadu restaurants. Ask me to find restaurants, check table availability, or view your booking passcodes!",
      quickPrompts: [
        "≡ƒì╜∩╕Å Find restaurants near me",
        "≡ƒƒó Restaurants open now",
        "≡ƒ¬æ Tables available now",
        "≡ƒÆ░ Restaurants under Γé╣500",
        "≡ƒôì Restaurants near me",
        "≡ƒñû Recommend a restaurant"
      ]
    }
  };

  const activeRoleKey = isAdmin ? "ADMIN" : (isOwner ? "RESTAURANT_OWNER" : "CUSTOMER");
  const config = ROLE_CONFIG[activeRoleKey];

  const [messages, setMessages] = useState([]);

  // Reset messages when role changes
  useEffect(() => {
    setMessages([
      {
        id: 1,
        sender: "bot",
        text: config.welcomeText,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      }
    ]);
    setPendingMutation(null);
  }, [user?.role]);

  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    if (isOpen) {
      scrollToBottom();
    }
  }, [messages, isOpen]);

  // Execute confirmed mutation for Owner AI (Confirm-Then-Execute Flow)
  const handleConfirmMutation = async (action, params) => {
    setLoading(true);
    try {
      const res = await api.executeOwnerAIMutation(params.restaurant_id, action, params);
      setMessages((prev) => [
        ...prev,
        {
          id: Date.now(),
          sender: "bot",
          text: res.message || "Γ£ô Operation completed successfully.",
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        }
      ]);
    } catch (err) {
      setMessages((prev) => [
        ...prev,
        {
          id: Date.now(),
          sender: "bot",
          text: `Γ¥î Mutation failed: ${err.message || "Unauthorized action"}`,
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        }
      ]);
    } finally {
      setLoading(false);
      setPendingMutation(null);
    }
  };

  const handleSendMessage = async (textToSend) => {
    const query = textToSend || inputMessage;
    if (!query.trim()) return;

    const userMsgId = Date.now();
    const userMsg = {
      id: userMsgId,
      sender: "user",
      text: query,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };

    setMessages((prev) => [...prev, userMsg]);
    if (!textToSend) setInputMessage("");
    setLoading(true);

    const lowerQ = query.toLowerCase();

    // 1. ADMIN AI SUPERVISOR ROUTING
    if (isAdmin) {
      try {
        const res = await api.getAdminAI(query);
        setMessages((prev) => [
          ...prev,
          {
            id: Date.now() + 1,
            sender: "bot",
            text: res.answer,
            metrics: res.metrics,
            timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
          }
        ]);
      } catch (err) {
        setMessages((prev) => [
          ...prev,
          {
            id: Date.now() + 1,
            sender: "bot",
            text: "I don't have enough verified data to provide that information.",
            timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
          }
        ]);
      } finally {
        setLoading(false);
      }
      return;
    }

    // 2. OWNER AI ASSISTANT ROUTING
    if (isOwner) {
      try {
        const res = await api.getOwnerAI(query, user?.restaurant_id || null);

        let msgObj = {
          id: Date.now() + 1,
          sender: "bot",
          text: res.answer,
          requiresConfirmation: res.requires_confirmation,
          pendingAction: res.pending_action,
          pendingParams: res.pending_params,
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };

        if (res.requires_confirmation) {
          setPendingMutation({ action: res.pending_action, params: res.pending_params });
        }

        setMessages((prev) => [...prev, msgObj]);
      } catch (err) {
        setMessages((prev) => [
          ...prev,
          {
            id: Date.now() + 1,
            sender: "bot",
            text: `ΓÜá∩╕Å ${err.message || "I don't have enough verified information to answer that. Try asking about today's bookings, table status, or waiting time."}`,
            timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
          }
        ]);
      } finally {
        setLoading(false);
      }
      return;
    }

    // 3. CUSTOMER AI ROUTING
    // Check if query is about customer's own bookings or passcodes
    if (lowerQ.includes("my booking") || lowerQ.includes("my passcode") || lowerQ.includes("my check-in code") || lowerQ.includes("my code") || lowerQ.includes("booking status") || lowerQ.includes("upcoming booking")) {
      try {
        const myBookings = await api.getMyBookings();
        if (myBookings && myBookings.length > 0) {
          const bListStr = myBookings.slice(0, 3).map((b) => 
            `ΓÇó **${b.restaurant_name || "Restaurant"}** (${b.booking_date} ${b.booking_time})\n  Passcode: \`${b.verification_code}\` | Status: ${b.status}`
          ).join("\n\n");

          setMessages((prev) => [
            ...prev,
            {
              id: Date.now() + 1,
              sender: "bot",
              text: `≡ƒôà **Your Authenticated Upcoming Bookings:**\n\n${bListStr}\n\nShow your 6-digit passcode upon arrival for **+10 Loyalty Points**!`,
              timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            }
          ]);
        } else {
          setMessages((prev) => [
            ...prev,
            {
              id: Date.now() + 1,
              sender: "bot",
              text: "You don't have any active bookings right now. Use the search bar above to discover top Tamil Nadu spots and reserve a table instantly!",
              timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            }
          ]);
        }
      } catch (err) {
        setMessages((prev) => [
          ...prev,
          {
            id: Date.now() + 1,
            sender: "bot",
            text: "Please sign in to view your personal booking passcodes and loyalty status.",
            timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
          }
        ]);
      } finally {
        setLoading(false);
      }
      return;
    }

    // Check if query is about loyalty points
    if (lowerQ.includes("loyalty") || lowerQ.includes("my points") || lowerQ.includes("reward points")) {
      try {
        const loyaltyData = await api.getLoyalty();
        const pts = loyaltyData.total_points || 0;
        setMessages((prev) => [
          ...prev,
          {
            id: Date.now() + 1,
            sender: "bot",
            text: `≡ƒÅå **Your Loyalty Balance:**\n\nYou currently have **${pts} Loyalty Points**! Earn +10 points for every verified table check-in across Tamil Nadu restaurants.`,
            timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
          }
        ]);
      } catch (err) {
        setMessages((prev) => [
          ...prev,
          {
            id: Date.now() + 1,
            sender: "bot",
            text: "Please sign in to view your accumulated loyalty points balance.",
            timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
          }
        ]);
      } finally {
        setLoading(false);
      }
      return;
    }

    // Check if query is about check-in process or 6-digit code
    if (lowerQ.includes("check-in process") || lowerQ.includes("how to check in") || lowerQ.includes("checkin process") || lowerQ.includes("6-digit code")) {
      setMessages((prev) => [
        ...prev,
        {
          id: Date.now() + 1,
          sender: "bot",
          text: "≡ƒöæ **Check-In Verification Guide:**\n\n1. Book a table at any restaurant.\n2. Receive a unique 6-digit verification code.\n3. Show code to restaurant staff upon arrival.\n4. Staff verifies code in Owner Terminal to confirm arrival and unlock **+10 Loyalty Points**!",
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        }
      ]);
      setLoading(false);
      return;
    }

    // Check if query is about cancellation process
    if (lowerQ.includes("cancel") || lowerQ.includes("cancellation")) {
      setMessages((prev) => [
        ...prev,
        {
          id: Date.now() + 1,
          sender: "bot",
          text: "≡ƒÜ½ **Cancellation Policy & Process:**\n\nYou can cancel any upcoming reservation directly from your Profile page -> My Bookings section. Free cancellations are allowed up to your scheduled time slot, immediately releasing the table.",
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        }
      ]);
      setLoading(false);
      return;
    }

    // Check if query is about verified reviews
    if (lowerQ.includes("verified review") || lowerQ.includes("how to review")) {
      setMessages((prev) => [
        ...prev,
        {
          id: Date.now() + 1,
          sender: "bot",
          text: "Γ¡É **100% Verified Reviews:**\n\nOnly diners with a confirmed and checked-in booking can leave a review. This ensures all ratings and reviews across SmartFinder are authentic!",
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        }
      ]);
      setLoading(false);
      return;
    }

    // Default Customer Recommendation API call
    try {
      const res = await api.getAIRecommendations(query);

      let botResponseMsg = {
        id: Date.now() + 2,
        sender: "bot",
        text: res.recommendation_reason || "Here are the top restaurant matches based on your request:",
        recommendations: res.best_match ? [res.best_match, ...(res.alternatives || []).map(a => a.restaurant)] : [],
        intent: res.parsed_intent,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      };

      setMessages((prev) => [...prev, botResponseMsg]);
    } catch (err) {
      setMessages((prev) => [
        ...prev,
        {
          id: Date.now() + 3,
          sender: "bot",
          text: "I don't have enough verified information to answer that. Try asking for specific dishes like 'Authentic Dosa in Chennai' or 'Biryani in Dindigul'.",
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        }
      ]);
    } finally {
      setLoading(false);
    }
  };

  const IconComponent = config.icon;

  return (
    <div style={{ position: "fixed", bottom: "24px", right: "24px", zIndex: 999 }}>
      {/* Floating Trigger Button */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          style={{
            background: config.gradient,
            color: "#FFFFFF",
            border: "none",
            borderRadius: "var(--radius-full)",
            padding: "0.85rem 1.35rem",
            fontSize: "0.95rem",
            fontWeight: 800,
            cursor: "pointer",
            boxShadow: "0 10px 25px -5px rgba(0, 0, 0, 0.4)",
            display: "flex",
            alignItems: "center",
            gap: "0.6rem",
            transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)"
          }}
          onMouseOver={(e) => (e.currentTarget.style.transform = "scale(1.05) translateY(-2px)")}
          onMouseOut={(e) => (e.currentTarget.style.transform = "scale(1) translateY(0)")}
        >
          <div style={{
            position: "relative",
            display: "flex",
            alignItems: "center",
            justifyContent: "center"
          }}>
            <Sparkles size={18} />
            <span className="pulse-dot pulse-green" style={{ position: "absolute", top: "-2px", right: "-2px" }} />
          </div>
          <span>{config.title}</span>
        </button>
      )}

      {/* Expanded Chat Box */}
      {isOpen && (
        <div style={{
          width: "400px",
          height: "560px",
          backgroundColor: "var(--bg-card)",
