import React, { useState } from "react";
import confetti from "canvas-confetti";
import { 
  ShieldCheck, X, CheckCircle2, AlertCircle, Award, 
  User, Calendar, Clock, Utensils
} from "lucide-react";
import { api } from "../services/api";

export function CheckInModal({ onClose, onCheckInSuccess }) {
  const [code, setCode] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [successData, setSuccessData] = useState(null);

  const handleVerify = async (e) => {
    e.preventDefault();
    if (!code.trim()) return;

    setError(null);
    setLoading(true);

    try {
      const res = await api.verifyCheckInCode(code.trim());
      setSuccessData(res);

      // Trigger Confetti
      confetti({
        particleCount: 100,
        spread: 60,
        origin: { y: 0.6 },
        colors: ["#10B981", "#0E5E4E", "#E59500"]
      });

      onCheckInSuccess?.(res);
    } catch (err) {
      setError(err.message || "Invalid or expired check-in code.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div 
        className="modal-content" 
        onClick={(e) => e.stopPropagation()}
        style={{ maxWidth: "480px", padding: "2rem" }}
      >
        {/* Header */}
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: "1.25rem" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
            <div style={{
              width: "36px",
              height: "36px",
              borderRadius: "10px",
              backgroundColor: "var(--secondary)",
              color: "#FFFFFF",
              display: "flex",
              alignItems: "center",
              justifyContent: "center"
            }}>
              <ShieldCheck size={20} />
            </div>
            <div>
              <h2 style={{ fontSize: "1.25rem", fontWeight: 800 }}>
                Owner Check-In Terminal
              </h2>
              <p style={{ fontSize: "0.78rem", color: "var(--text-muted)" }}>
                Verify 6-digit customer reservation code
              </p>
            </div>
          </div>
          <button onClick={onClose} style={{ color: "var(--text-muted)" }}>
            <X size={20} />
          </button>
        </div>

        {successData ? (
          <div style={{ textAlign: "center", animation: "fadeIn 0.3s ease" }}>
            <div style={{
              width: "56px",
              height: "56px",
              borderRadius: "50%",
              backgroundColor: "var(--secondary-light)",
              color: "var(--secondary)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
