          gap: "0.65rem",
          width: "max-content",
          padding: "0.25rem 0",
        }}
      >
        {CUISINE_CHIPS.map((chip) => {
          const isActive = activeCuisine?.toLowerCase() === chip.query.toLowerCase();
          return (
            <button
              key={chip.query}
              onClick={() => onSelectCuisine(isActive ? "" : chip.query)}
              style={{
