    "Best Biryani in Dindigul within 5 km radius",
    "Traditional Banana Leaf Meals in Tirunelveli"
  ];

  const handleDetectLocation = () => {
    if (!navigator.geolocation) {
      setGeoError("Geolocation is not supported by your browser.");
      return;
    }

    setGeoLoading(true);
    setGeoError(null);

