import React, { useState, useEffect } from "react";
import { 
  Navigation, MapPin, Compass, Car, Clock, ShieldCheck, 
  ExternalLink, Layers, ZoomIn, ZoomOut, Utensils, X, Locate, RefreshCw
} from "lucide-react";

export function InteractiveMap({ 
  restaurants = [], 
  selectedRestaurant, 
  onSelectRestaurant, 
  userLocation = { lat: 13.0827, lng: 80.2707, city: "Chennai" },
  onClose
}) {
  const [mapMode, setMapMode] = useState("interactive"); // 'interactive', 'satellite', 'google_embed'
  const [currentGPS, setCurrentGPS] = useState(userLocation);
  const [trackingGPS, setTrackingGPS] = useState(false);
  const [navigating, setNavigating] = useState(false);

  const target = selectedRestaurant || (restaurants.length > 0 ? restaurants[0] : null);

  // Attempt real-time browser GPS tracking
  const handleDetectGPS = () => {
    if (!navigator.geolocation) return;
    setTrackingGPS(true);

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setTrackingGPS(false);
        setCurrentGPS({
          lat: pos.coords.latitude,
          lng: pos.coords.longitude,
          city: "GPS Detected Position"
        });
      },
      (err) => {
        setTrackingGPS(false);
        // Default to central Chennai if permission denied
        setCurrentGPS({
          lat: 13.0827,
          lng: 80.2707,
          city: "Chennai Central"
        });
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };

  useEffect(() => {
    handleDetectGPS();
  }, []);

  const openGoogleMapsDirections = () => {
    if (!target) return;
    const originStr = currentGPS?.lat ? `${currentGPS.lat},${currentGPS.lng}` : "Chennai,Tamil+Nadu";
    const destStr = target.lat ? `${target.lat},${target.lng}` : encodeURIComponent(`${target.name}, ${target.city}, Tamil Nadu`);
    const googleUrl = `https://www.google.com/maps/dir/?api=1&origin=${originStr}&destination=${destStr}&travelmode=driving`;
    window.open(googleUrl, "_blank");
  };

  return (
    <div style={{
      backgroundColor: "var(--bg-card)",
      borderRadius: "var(--radius-xl)",
      border: "1.5px solid var(--border)",
      overflow: "hidden",
      boxShadow: "var(--shadow-xl)",
      display: "flex",
      flexDirection: "column",
      height: "600px",
      position: "relative",
      fontFamily: "var(--font-sans)"
    }}>
      {/* Top Map Header & Controls */}
      <div style={{
        backgroundColor: "#0F172A",
        color: "#FFFFFF",
        padding: "0.85rem 1.25rem",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        zIndex: 20,
        boxShadow: "var(--shadow-md)"
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: "0.6rem" }}>
          <div style={{
            width: "36px",
            height: "36px",
            borderRadius: "10px",
            background: "linear-gradient(135deg, #FF541E 0%, #D84E10 100%)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            color: "#FFFFFF",
            boxShadow: "0 4px 12px rgba(255, 84, 30, 0.4)"
          }}>
            <Navigation size={20} />
          </div>
          <div>
            <div style={{ fontWeight: 900, fontSize: "1rem", color: "#FFFFFF" }}>
              Google Maps Live Route & Navigation
            </div>
            <div style={{ fontSize: "0.72rem", color: "#94A3B8", fontWeight: 600, display: "flex", alignItems: "center", gap: "0.4rem" }}>
              <span className="pulse-dot pulse-green" />
              <span>
                {currentGPS.lat ? `GPS: ${currentGPS.lat.toFixed(4)}, ${currentGPS.lng.toFixed(4)}` : "Detecting Location..."}
              </span>
            </div>
          </div>
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
          {/* Locate Me GPS Button */}
          <button
            onClick={handleDetectGPS}
            disabled={trackingGPS}
            style={{
              backgroundColor: trackingGPS ? "#334155" : "#2563EB",
              color: "#FFFFFF",
              border: "none",
              padding: "0.4rem 0.8rem",
              borderRadius: "var(--radius-full)",
              fontSize: "0.78rem",
              fontWeight: 800,
              cursor: "pointer",
              display: "flex",
              alignItems: "center",
              gap: "0.35rem",
              boxShadow: "0 4px 12px rgba(37, 99, 235, 0.3)"
            }}
            title="Center map around your exact current GPS coordinates"
          >
            <Locate size={14} className={trackingGPS ? "spin" : ""} />
            <span>{trackingGPS ? "LOCATING..." : "MY LOCATION"}</span>
          </button>

          {/* Map Mode Switcher */}
          <div style={{
            display: "flex",
            backgroundColor: "#1E293B",
            padding: "0.2rem",
            borderRadius: "var(--radius-full)",
            border: "1px solid #334155"
          }}>
            <button
              onClick={() => setMapMode("interactive")}
              style={{
                padding: "0.35rem 0.7rem",
                borderRadius: "var(--radius-full)",
                border: "none",
                fontSize: "0.75rem",
                fontWeight: 800,
                cursor: "pointer",
                backgroundColor: mapMode === "interactive" ? "var(--primary)" : "transparent",
                color: mapMode === "interactive" ? "#FFFFFF" : "#94A3B8"
              }}
            >
              Custom View
            </button>

            <button
              onClick={() => setMapMode("google_embed")}
              style={{
                padding: "0.35rem 0.7rem",
                borderRadius: "var(--radius-full)",
                border: "none",
                fontSize: "0.75rem",
                fontWeight: 800,
                cursor: "pointer",
                backgroundColor: mapMode === "google_embed" ? "var(--primary)" : "transparent",
                color: mapMode === "google_embed" ? "#FFFFFF" : "#94A3B8"
              }}
            >
              Google Map Embed
            </button>
          </div>

