import React, { createContext, useContext, useState, useEffect, useCallback, useRef } from "react";
import { api } from "../services/api";

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(localStorage.getItem("srf_token") || null);
  const [loading, setLoading] = useState(true);

  // Ref to hold the role-switch navigation callback registered by AppContent
  const onRoleSwitchRef = useRef(null);

  // Register a callback that fires after every successful role switch
  const registerRoleSwitchHandler = useCallback((fn) => {
    onRoleSwitchRef.current = fn;
  }, []);

  // Core login ΓÇö sets token + user state
  const login = useCallback(async (email, password) => {
    const res = await api.login({ email, password });
    localStorage.setItem("srf_token", res.access_token);
    setToken(res.access_token);
    const nextUser = {
      id: res.user_id,
      email: res.email,
      full_name: res.full_name,
      role: res.role,
    };
    setUser(nextUser);
    return { res, role: res.role };
  }, []);

  const register = useCallback(async (userData) => {
    const res = await api.register(userData);
    localStorage.setItem("srf_token", res.access_token);
    setToken(res.access_token);
    setUser({
      id: res.user_id,
      email: res.email,
      full_name: res.full_name,
      role: res.role,
    });
    return res;
  }, []);

  const logout = useCallback(() => {
    localStorage.removeItem("srf_token");
    setToken(null);
    setUser(null);
  }, []);

  // Demo quick-switch ΓÇö defined as a regular function so it's available
  // immediately (no hoisting issue with useEffect on mount)
  const loginDemoUser = useCallback(async (roleType) => {
    try {
      let result;
      if (roleType === "customer") {
        result = await login("arun@example.com", "customer123");
      } else if (roleType === "owner") {
        result = await login("owner@anjappar.tn", "owner123");
      } else if (roleType === "admin") {
        result = await login("admin@smartfinder.tn", "admin123");
      } else {
        return;
      }

      // After successful login, fire the navigation callback
      if (onRoleSwitchRef.current && result?.role) {
        onRoleSwitchRef.current(result.role);
      }
    } catch (e) {
      console.warn("Demo login failed:", e.message || e);
    }
  }, [login]);

  // On mount: restore session or default-login as customer
  useEffect(() => {
    async function initUser() {
      const storedToken = localStorage.getItem("srf_token");
      if (storedToken) {
        try {
          const userData = await api.getMe();
          setUser(userData);
        } catch (err) {
          console.error("Session restore failed, re-logging as customer", err);
          logout();
          // Fresh start ΓÇö login as demo customer
          try {
            await login("arun@example.com", "customer123");
          } catch (_) {}
        }
      } else {
        // No token at all ΓÇö auto-login as demo customer
        try {
          await login("arun@example.com", "customer123");
        } catch (_) {}
      }
      setLoading(false);
    }
    initUser();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); // run once on mount only

  return (
    <AuthContext.Provider
      value={{
        user,
        token,
        loading,
        login,
        register,
        logout,
        loginDemoUser,
        registerRoleSwitchHandler,
        isAuthenticated: !!user,
        isCustomer: user?.role === "CUSTOMER",
        isOwner: user?.role === "RESTAURANT_OWNER",
        isAdmin: user?.role === "ADMIN",
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

import React, { createContext, useContext, useState, useEffect } from "react";

const RealtimeContext = createContext(null);

export function RealtimeProvider({ children }) {
  const [liveUpdates, setLiveUpdates] = useState({});
  const [notification, setNotification] = useState(null);
  const [wsConnected, setWsConnected] = useState(false);

  useEffect(() => {
    let ws = null;
    let reconnectTimeout = null;

    function connect() {
      try {
        ws = new WebSocket("ws://127.0.0.1:8000/api/restaurants/ws/live-updates");

        ws.onopen = () => {
          setWsConnected(true);
        };

        ws.onmessage = (event) => {
          try {
            const data = JSON.parse(event.data);
            if (data.type === "AVAILABILITY_UPDATE") {
              setLiveUpdates((prev) => ({
                ...prev,
                [data.restaurant_id]: data,
              }));
              // Show notification pill
              setNotification({
                title: "Live Status Update",
                message: `Restaurant availability updated in real-time.`,
                timestamp: Date.now(),
              });
              setTimeout(() => setNotification(null), 4000);
            }
          } catch (err) {
            console.error("WS parse error", err);
          }
        };

        ws.onclose = () => {
          setWsConnected(false);
          reconnectTimeout = setTimeout(connect, 3000);
        };

        ws.onerror = () => {
          ws.close();
        };
      } catch (err) {
        console.warn("WebSocket connection error:", err);
      }
    }

    connect();

    return () => {
      if (ws) ws.close();
      if (reconnectTimeout) clearTimeout(reconnectTimeout);
    };
  }, []);

  return (
    <RealtimeContext.Provider value={{ liveUpdates, notification, wsConnected }}>
      {children}
    </RealtimeContext.Provider>
  );
}

export function useRealtime() {
  const context = useContext(RealtimeContext);
  if (!context) {
    throw new Error("useRealtime must be used within a RealtimeProvider");
  }
  return context;
}

import React, { createContext, useContext, useState, useEffect } from "react";

const ThemeContext = createContext({
  theme: "light",
  toggleTheme: () => {},
  isDark: false,
});

export function ThemeProvider({ children }) {
  const [theme, setTheme] = useState(() => {
    try {
      return localStorage.getItem("srf_theme") || "light";
    } catch {
      return "light";
    }
  });

  useEffect(() => {
    document.documentElement.setAttribute("data-theme", theme);
    document.body.setAttribute("data-theme", theme);
    document.documentElement.style.colorScheme = theme;
    document.body.style.colorScheme = theme;
    if (theme === "dark") {
      document.documentElement.classList.add("dark");
      document.body.classList.add("dark");
    } else {
      document.documentElement.classList.remove("dark");
      document.body.classList.remove("dark");
    }
    try {
      localStorage.setItem("srf_theme", theme);
    } catch {}
  }, [theme]);

  const toggleTheme = () => {
    setTheme((prev) => (prev === "dark" ? "light" : "dark"));
  };

  const isDark = theme === "dark";

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme, isDark }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  return useContext(ThemeContext);
}

import { useState, useEffect, useCallback } from "react";

const STORAGE_KEY = "srf_recently_viewed";
const MAX_ITEMS = 8;

export function useRecentlyViewed() {
  const [recentlyViewed, setRecentlyViewed] = useState(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      return stored ? JSON.parse(stored) : [];
    } catch {
      return [];
    }
  });

  const addToRecents = useCallback((restaurant) => {
    if (!restaurant?.id) return;
    setRecentlyViewed((prev) => {
      // Remove if already present, then prepend
      const filtered = prev.filter((r) => r.id !== restaurant.id);
      const next = [
        {
          id: restaurant.id,
          name: restaurant.name,
          city: restaurant.city,
          cuisine: restaurant.cuisine,
          rating: restaurant.rating,
          image_url: restaurant.image_url,
          price_range: restaurant.price_range,
          avg_cost_for_two: restaurant.avg_cost_for_two,
          is_open: restaurant.is_open,
          table_status: restaurant.table_status,
          viewedAt: Date.now(),
        },
        ...filtered,
      ].slice(0, MAX_ITEMS);
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      } catch {}
      return next;
    });
  }, []);

  const clearRecents = useCallback(() => {
    setRecentlyViewed([]);
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch {}
  }, []);

  return { recentlyViewed, addToRecents, clearRecents };
}

