              {m?.completed_visits || 0}
            </div>
          </div>

          <div style={{ backgroundColor: "var(--bg-card)", padding: "1.25rem", borderRadius: "var(--radius-xl)", border: "1px solid var(--border)", boxShadow: "var(--shadow-sm)" }}>
