              onClick={() => setActiveTab(t.key)}
              style={{
                padding: "0.75rem 1.25rem",
                fontWeight: 700,
                fontSize: "0.9rem",
                color: activeTab === t.key ? "var(--primary)" : "var(--text-muted)",
