                <MapPin size={18} style={{ color: "var(--primary)" }} />
                <h3 style={{ fontSize: "1.1rem", fontWeight: 800 }}>Top Cities by Network Presence</h3>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: "0.75rem" }}>
                {stats?.top_cities?.map((c, i) => (
