              <thead>
                <tr style={{ borderBottom: "2px solid var(--border)", textAlign: "left", color: "var(--text-muted)" }}>
                  <th style={{ padding: "0.75rem" }}>Name</th>
                  <th style={{ padding: "0.75rem" }}>Email</th>
                  <th style={{ padding: "0.75rem" }}>Phone</th>
                  <th style={{ padding: "0.75rem" }}>Role</th>
                  <th style={{ padding: "0.75rem" }}>Registered</th>
                </tr>
              </thead>
              <tbody>
                {usersList.map((u) => (
                  <tr key={u.id} style={{ borderBottom: "1px solid var(--border)" }}>
                    <td style={{ padding: "0.75rem", fontWeight: 700 }}>{u.full_name}</td>
                    <td style={{ padding: "0.75rem" }}>{u.email}</td>
                    <td style={{ padding: "0.75rem" }}>{u.phone || "-"}</td>
                    <td style={{ padding: "0.75rem" }}>
                      <span className={`badge ${u.role === "ADMIN" ? "badge-primary" : (u.role === "RESTAURANT_OWNER" ? "badge-limited" : "badge-verified")}`}>
                        {u.role}
                      </span>
                    </td>
                    <td style={{ padding: "0.75rem", color: "var(--text-muted)" }}>{new Date(u.created_at).toLocaleDateString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Tab 3: Complaints Resolution */}
        {activeTab === "complaints" && (
          <div style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
            {complaints.map((c) => (
              <div
                key={c.id}
                style={{
                  backgroundColor: "var(--bg-card)",
                  borderRadius: "var(--radius-xl)",
                  border: "1px solid var(--border)",
                  padding: "1.5rem",
                  boxShadow: "var(--shadow-sm)"
                }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "0.5rem" }}>
                  <div>
                    <span style={{ fontWeight: 800, fontSize: "1.1rem" }}>{c.restaurant_name}</span>
                    <span style={{ color: "var(--text-muted)", fontSize: "0.85rem", marginLeft: "0.5rem" }}>by {c.customer_name} ({c.complaint_type})</span>
                  </div>
                  <span className={`badge ${c.status === "RESOLVED" ? "badge-available" : (c.status === "RESPONDED" ? "badge-limited" : "badge-full")}`}>
                    {c.status}
                  </span>
                </div>

                <p style={{ fontSize: "0.88rem", color: "var(--text-main)", marginBottom: "0.75rem" }}>
                  {c.description}
                </p>

                {c.owner_response && (
                  <div style={{ backgroundColor: "var(--bg-main)", padding: "0.6rem 0.85rem", borderRadius: "var(--radius-md)", fontSize: "0.82rem", marginBottom: "0.75rem", border: "1px solid var(--border)" }}>
                    <strong>Owner:</strong> {c.owner_response}
                  </div>
                )}

                {c.admin_notes && (
                  <div style={{ backgroundColor: "var(--indigo-light)", padding: "0.6rem 0.85rem", borderRadius: "var(--radius-md)", fontSize: "0.82rem", marginBottom: "0.75rem", color: "var(--text-main)", border: "1px solid var(--border)" }}>
                    <strong>Admin Note:</strong> {c.admin_notes}
                  </div>
                )}

                <button
                  onClick={() => setSelectedComplaint(c)}
                  className="btn btn-secondary btn-sm"
                  style={{ fontWeight: 700 }}
                >
                  Resolve / Add Admin Action
                </button>
              </div>
            ))}
          </div>
        )}

        {/* Resolution Modal */}
        {selectedComplaint && (
          <div className="modal-overlay" onClick={() => setSelectedComplaint(null)}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()} style={{ maxWidth: "500px", padding: "2rem" }}>
              <h3 style={{ fontSize: "1.25rem", fontWeight: 800, marginBottom: "0.5rem" }}>
                Resolve Grievance #{selectedComplaint.id}
              </h3>
              <form onSubmit={handleResolveComplaint}>
                <div style={{ marginBottom: "1rem" }}>
                  <label style={{ fontSize: "0.8rem", fontWeight: 700, display: "block", marginBottom: "0.3rem" }}>STATUS</label>
                  <select
                    value={newStatus}
                    onChange={(e) => setNewStatus(e.target.value)}
                    style={{ width: "100%", padding: "0.6rem", borderRadius: "var(--radius-md)", fontWeight: 600 }}
                  >
                    <option value="RESOLVED">RESOLVED</option>
                    <option value="RESPONDED">RESPONDED</option>
                    <option value="PENDING">PENDING</option>
                  </select>
                </div>

                <div style={{ marginBottom: "1.5rem" }}>
                  <label style={{ fontSize: "0.8rem", fontWeight: 700, display: "block", marginBottom: "0.3rem" }}>ADMIN RESOLUTION NOTES</label>
                  <textarea
                    rows={3}
                    value={adminNote}
                    onChange={(e) => setAdminNote(e.target.value)}
                    placeholder="Document resolution or corrective action..."
                    style={{ width: "100%", padding: "0.6rem", borderRadius: "var(--radius-md)" }}
                  />
                </div>

                <div style={{ display: "flex", gap: "0.5rem" }}>
                  <button type="button" onClick={() => setSelectedComplaint(null)} className="btn btn-secondary" style={{ flex: 1 }}>
                    Cancel
                  </button>
                  <button type="submit" className="btn btn-primary" style={{ flex: 1 }}>
                    Save Resolution
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { 
  Sparkles, MapPin, Utensils, Star, Clock, ShieldCheck, 
  ArrowRight, Award, TrendingUp, Compass, Heart, History
} from "lucide-react";
import { HeroSearch } from "../components/HeroSearch";
import { PromoBannerCarousel } from "../components/PromoBannerCarousel";
import { RestaurantCard } from "../components/RestaurantCard";
import { TrendingCarousel } from "../components/TrendingCarousel";
import { CuisineChips } from "../components/CuisineChips";
import { api } from "../services/api";
import { useAuth } from "../context/AuthContext";

export function HomePage({ 
  onSearch, 
  onSelectRestaurant, 
  onBookRestaurant, 
  onDirections, 
  onOpenAI, 
  cities = [], 
  cuisines = [],
  selectedCity,
  onSelectCity,
  recentlyViewed = []
}) {
  const { user } = useAuth();
  const [featuredRestaurants, setFeaturedRestaurants] = useState([]);
  const [topRatedRestaurants, setTopRatedRestaurants] = useState([]);
  const [favorites, setFavorites] = useState(new Set());
  const [loading, setLoading] = useState(true);
  const [activeCuisine, setActiveCuisine] = useState("");
  const [geoLoading, setGeoLoading] = useState(false);

  const handleNearMeClick = () => {
    setGeoLoading(true);
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setGeoLoading(false);
          onSearch({
            user_lat: pos.coords.latitude,
            user_lng: pos.coords.longitude,
            sort_by: "distance"
          });
        },
        (err) => {
          setGeoLoading(false);
          onSearch({
            user_lat: 13.0827,
            user_lng: 80.2707,
            sort_by: "distance"
          });
        },
        { enableHighAccuracy: true, timeout: 10000 }
      );
    } else {
      setGeoLoading(false);
      onSearch({
        user_lat: 13.0827,
        user_lng: 80.2707,
        sort_by: "distance"
      });
    }
  };

  useEffect(() => {
    async function loadHomeData() {
      setLoading(true);
      try {
        const list = await api.getRestaurants({ city: selectedCity === "All Cities" ? "" : selectedCity });
        setFeaturedRestaurants(list);
        
        // Sort by rating for top-rated
        const sorted = [...list].sort((a, b) => b.rating - a.rating);
        setTopRatedRestaurants(sorted.slice(0, 6));

        // Load favorites
        try {
          const prof = await api.getProfile();
          if (prof?.favorites) {
            setFavorites(new Set(prof.favorites.map((f) => f.id)));
          }
        } catch (e) {}
      } catch (err) {
        console.error("Failed to load home restaurants", err);
      } finally {
        setLoading(false);
      }
    }
    loadHomeData();
  }, [selectedCity]);

  const handleCuisineSelect = (cuisineName) => {
    setActiveCuisine(cuisineName);
    onSearch({
      city: selectedCity === "All Cities" ? "" : selectedCity,
      cuisine: cuisineName
    });
  };

  const handleToggleFavorite = async (restId) => {
    try {
      const isFav = favorites.has(restId);
      if (isFav) {
        await api.removeFavorite(restId);
        setFavorites((prev) => {
          const next = new Set(prev);
          next.delete(restId);
          return next;
        });
      } else {
        await api.addFavorite(restId);
        setFavorites((prev) => new Set(prev).add(restId));
      }
    } catch (err) {
      console.error("Favorite toggle error", err);
    }
  };

  const CITY_SPOTLIGHTS = [
    { name: "Chennai", subtitle: "Capital of Chettinad & Tiffin", img: "https://images.unsplash.com/photo-1589301760014-d929f3979dbc?w=600&auto=format&fit=crop&q=80" },
    { name: "Coimbatore", subtitle: "Kongunadu Flavor Trail", img: "https://images.unsplash.com/photo-1610192244261-3f33de3f55e4?w=600&auto=format&fit=crop&q=80" },
    { name: "Madurai", subtitle: "Kari Dosa & Jigarthanda Capital", img: "https://images.unsplash.com/photo-1546833999-b9f581a1996d?w=600&auto=format&fit=crop&q=80" },
    { name: "Dindigul", subtitle: "Legendary Seeraga Samba Biryani", img: "https://images.unsplash.com/photo-1546833999-b9f581a1996d?w=600&auto=format&fit=crop&q=80" }
  ];

