        <div className="container">
          <h2 style={{ fontSize: "1.5rem", fontWeight: 900, color: "var(--text-main)", marginBottom: "1.1rem" }}>
            Hi {user?.name?.split(" ")[0] || "Sankar"}, Dine Anytime!
          </h2>

          <div style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))",
            gap: "1rem"
          }}>
            {/* 1. Lunch */}
            <div
              onClick={() => onSearch({ search: "Lunch Meals", city: selectedCity === "All Cities" ? "" : selectedCity })}
              style={{
                backgroundColor: "var(--bg-card)",
                borderRadius: "var(--radius-lg)",
                padding: "0.85rem 1.1rem",
                display: "flex",
                alignItems: "center",
                gap: "0.85rem",
                boxShadow: "var(--shadow-sm)",
                border: "1.5px solid var(--border)",
                cursor: "pointer",
                transition: "all 0.2s ease"
              }}
              onMouseOver={(e) => { e.currentTarget.style.transform = "translateY(-3px)"; e.currentTarget.style.boxShadow = "var(--shadow-md)"; e.currentTarget.style.borderColor = "var(--primary)"; }}
              onMouseOut={(e) => { e.currentTarget.style.transform = "translateY(0)"; e.currentTarget.style.boxShadow = "var(--shadow-sm)"; e.currentTarget.style.borderColor = "var(--border)"; }}
            >
              <div style={{
                width: "48px",
                height: "48px",
                borderRadius: "14px",
                backgroundColor: "#FFF3EB",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontSize: "1.5rem"
              }}>
                ≡ƒì¢
              </div>
              <span style={{ fontWeight: 800, fontSize: "1rem", color: "var(--text-main)" }}>Lunch</span>
            </div>

            {/* 2. Dinner */}
            <div
              onClick={() => onSearch({ search: "Dinner Chettinad", city: selectedCity === "All Cities" ? "" : selectedCity })}
              style={{
                backgroundColor: "var(--bg-card)",
                borderRadius: "var(--radius-lg)",
                padding: "0.85rem 1.1rem",
                display: "flex",
                alignItems: "center",
                gap: "0.85rem",
                boxShadow: "var(--shadow-sm)",
                border: "1.5px solid var(--border)",
                cursor: "pointer",
                transition: "all 0.2s ease"
              }}
              onMouseOver={(e) => { e.currentTarget.style.transform = "translateY(-3px)"; e.currentTarget.style.boxShadow = "var(--shadow-md)"; e.currentTarget.style.borderColor = "var(--primary)"; }}
              onMouseOut={(e) => { e.currentTarget.style.transform = "translateY(0)"; e.currentTarget.style.boxShadow = "var(--shadow-sm)"; e.currentTarget.style.borderColor = "var(--border)"; }}
            >
              <div style={{
                width: "48px",
                height: "48px",
                borderRadius: "14px",
                backgroundColor: "#FEF3C7",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontSize: "1.5rem"
              }}>
                ≡ƒÑÿ
              </div>
              <span style={{ fontWeight: 800, fontSize: "1rem", color: "var(--text-main)" }}>Dinner</span>
            </div>

