              </div>
              <span style={{ fontWeight: 800, fontSize: "1rem", color: "var(--text-main)" }}>Breakfast</span>
            </div>
          </div>
        </div>
      </section>



      {/* EazyDiner & OpenTable Prime Perks Section */}
