            padding: "0.75rem 0.85rem",
            borderRadius: "10px",
            fontSize: "0.82rem",
            fontWeight: 600,
            marginBottom: "1.25rem",
            display: "flex",
            alignItems: "center",
            gap: "0.4rem"
          }}>
            <AlertCircle size={16} />
            <span>{error}</span>
          </div>
        )}

