                required
                style={{
                  width: "100%",
                  padding: "0.8rem 1rem",
                  borderRadius: "12px",
                  backgroundColor: theme === "dark" ? "rgba(15, 23, 42, 0.7)" : "#F8FAFC",
                  border: "1px solid",
                  borderColor: theme === "dark" ? "#26334D" : "#CBD5E1",
                  color: theme === "dark" ? "#FFFFFF" : "#0F172A",
                  fontSize: "0.92rem",
                  outline: "none"
                }}
              />
            </div>
          )}

          {/* Email Input */}
          <div style={{ marginBottom: "1.25rem" }}>
            <label style={{ fontSize: "0.82rem", fontWeight: 700, color: theme === "dark" ? "#CBD5E1" : "#475569", marginBottom: "0.35rem", display: "block" }}>
              Email Address
            </label>
            <input
              type="email"
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              style={{
                width: "100%",
                padding: "0.8rem 1rem",
                borderRadius: "12px",
                backgroundColor: theme === "dark" ? "rgba(15, 23, 42, 0.7)" : "#F8FAFC",
                border: "1px solid",
                borderColor: theme === "dark" ? "#26334D" : "#CBD5E1",
                color: theme === "dark" ? "#FFFFFF" : "#0F172A",
                fontSize: "0.92rem",
                outline: "none"
              }}
            />
          </div>

          {/* Password Input */}
          <div style={{ marginBottom: "1.5rem" }}>
            <label style={{ fontSize: "0.82rem", fontWeight: 700, color: theme === "dark" ? "#CBD5E1" : "#475569", marginBottom: "0.35rem", display: "block" }}>
              Password
            </label>
            <div style={{ position: "relative" }}>
              <input
                type={showPassword ? "text" : "password"}
                placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                style={{
                  width: "100%",
                  padding: "0.8rem 2.6rem 0.8rem 1rem",
                  borderRadius: "12px",
                  backgroundColor: theme === "dark" ? "rgba(15, 23, 42, 0.7)" : "#F8FAFC",
                  border: "1px solid",
                  borderColor: theme === "dark" ? "#26334D" : "#CBD5E1",
                  color: theme === "dark" ? "#FFFFFF" : "#0F172A",
                  fontSize: "0.92rem",
                  outline: "none"
                }}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                style={{
                  position: "absolute",
                  right: "12px",
                  top: "50%",
                  transform: "translateY(-50%)",
                  background: "none",
                  border: "none",
                  color: theme === "dark" ? "#64748B" : "#94A3B8",
                  cursor: "pointer",
                  padding: "0.2rem"
                }}
              >
                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>
          </div>

          {isRegisterMode && (
            <div style={{ marginBottom: "1.5rem" }}>
              <label style={{ fontSize: "0.82rem", fontWeight: 700, color: theme === "dark" ? "#CBD5E1" : "#475569", marginBottom: "0.35rem", display: "block" }}>
                Select Role
              </label>
              <select
                value={role}
                onChange={(e) => setRole(e.target.value)}
                style={{
                  width: "100%",
                  padding: "0.8rem 1rem",
                  borderRadius: "12px",
                  backgroundColor: theme === "dark" ? "rgba(15, 23, 42, 0.7)" : "#F8FAFC",
                  border: "1px solid",
                  borderColor: theme === "dark" ? "#26334D" : "#CBD5E1",
                  color: theme === "dark" ? "#FFFFFF" : "#0F172A",
                  fontSize: "0.92rem",
                  fontWeight: 600
                }}
              >
                <option value="CUSTOMER">Customer / Diner</option>
                <option value="RESTAURANT_OWNER">Restaurant Owner</option>
                <option value="ADMIN">Platform Admin</option>
              </select>
            </div>
          )}

          {/* Submit Button matching image style */}
          <button
            type="submit"
            disabled={loading}
            style={{
              width: "100%",
              padding: "0.9rem",
              borderRadius: "14px",
              background: "linear-gradient(135deg, #FF3B5C 0%, #FF541E 100%)",
              color: "#FFFFFF",
              border: "none",
              fontSize: "1rem",
              fontWeight: 800,
              cursor: "pointer",
              boxShadow: "0 6px 20px rgba(255, 59, 92, 0.4)",
              transition: "transform 0.2s, boxShadow 0.2s"
            }}
            onMouseOver={(e) => (e.currentTarget.style.transform = "translateY(-1px)")}
            onMouseOut={(e) => (e.currentTarget.style.transform = "translateY(0)")}
          >
            {loading ? "AUTHENTICATING..." : (isRegisterMode ? "Register Account" : "Login to SmartFood")}
          </button>
        </form>
      </div>
    </div>
  );
}

