  initialParams = {},
  onSelectRestaurant,
  onBookRestaurant,
  onDirections,
  onOpenAI,
  cities = [],
  cuisines = []
}) {
  const { user } = useAuth();
  const [filters, setFilters] = useState({
    city: initialParams.city || "",
    cuisine: initialParams.cuisine || "",
    search: initialParams.search || "",
    user_lat: initialParams.user_lat || null,
    user_lng: initialParams.user_lng || null,
    price_range: "",
    min_rating: "",
    open_now: "",
    table_status: "",
    parking_status: "",
    sort_by: initialParams.sort_by || "rating"
  });

  const [restaurants, setRestaurants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState("split"); // 'grid', 'map', 'split'
  const [selectedMapRest, setSelectedMapRest] = useState(null);
  const [favorites, setFavorites] = useState(new Set());
  const [geoLoading, setGeoLoading] = useState(false);

  const handleNearMeClick = () => {
    setGeoLoading(true);
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setGeoLoading(false);
          setFilters((prev) => ({
            ...prev,
            user_lat: pos.coords.latitude,
            user_lng: pos.coords.longitude,
            sort_by: "distance"
          }));
        },
        (err) => {
          setGeoLoading(false);
          setFilters((prev) => ({
            ...prev,
            user_lat: 13.0827,
            user_lng: 80.2707,
            sort_by: "distance"
          }));
        },
        { enableHighAccuracy: true, timeout: 10000 }
      );
    } else {
      setGeoLoading(false);
      setFilters((prev) => ({
        ...prev,
        user_lat: 13.0827,
        user_lng: 80.2707,
        sort_by: "distance"
      }));
    }
  };

  // Sync initialParams changes (e.g. Near Me GPS trigger from home)
  useEffect(() => {
    if (initialParams) {
      setFilters((prev) => ({
        ...prev,
        city: initialParams.city !== undefined ? initialParams.city : prev.city,
        cuisine: initialParams.cuisine !== undefined ? initialParams.cuisine : prev.cuisine,
        search: initialParams.search !== undefined ? initialParams.search : prev.search,
        user_lat: initialParams.user_lat || null,
        user_lng: initialParams.user_lng || null,
        sort_by: initialParams.sort_by || prev.sort_by || "rating"
      }));
    }
  }, [initialParams]);

  // Load restaurants on filter change
  useEffect(() => {
    async function fetchResults() {
      setLoading(true);
      try {
        const data = await api.getRestaurants(filters);
        setRestaurants(data);
        if (data.length > 0 && !selectedMapRest) {
          setSelectedMapRest(data[0]);
        }
      } catch (err) {
        console.error("Search fetch error", err);
      } finally {
        setLoading(false);
      }
    }
    fetchResults();
  }, [filters]);

