                  backgroundColor: viewMode === "split" ? "var(--primary)" : "transparent",
                  color: viewMode === "split" ? "#FFFFFF" : "var(--text-muted)",
                  border: "none",
                  cursor: "pointer",
                  boxShadow: viewMode === "split" ? "0 2px 8px rgba(255, 84, 30, 0.3)" : "none",
                  transition: "all 0.2s ease"
                }}
              >
                <SlidersHorizontal size={15} />
                <span>Split View</span>
              </button>

              <button
                onClick={() => setViewMode("map")}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "0.35rem",
                  padding: "0.45rem 0.8rem",
                  borderRadius: "6px",
                  fontSize: "0.82rem",
                  fontWeight: 800,
                  backgroundColor: viewMode === "map" ? "var(--primary)" : "transparent",
                  color: viewMode === "map" ? "#FFFFFF" : "var(--text-muted)",
                  border: "none",
                  cursor: "pointer",
                  boxShadow: viewMode === "map" ? "0 2px 8px rgba(255, 84, 30, 0.3)" : "none",
                  transition: "all 0.2s ease"
                }}
              >
                <Map size={15} />
                <span>Map Only</span>
              </button>
            </div>
          </div>
        </div>



        {/* GPS Location Active Banner */}
        {filters.user_lat && filters.user_lng && (
          <div style={{
            backgroundColor: "#D1FAE5",
            color: "#065F46",
            border: "1.5px solid #34D399",
            borderRadius: "var(--radius-xl)",
            padding: "0.85rem 1.25rem",
            marginBottom: "1.25rem",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            fontWeight: 700,
            fontSize: "0.9rem",
            boxShadow: "var(--shadow-sm)"
          }}>
            <div style={{ display: "flex", alignItems: "center", gap: "0.6rem" }}>
              <span style={{ fontSize: "1.25rem" }}>≡ƒôì</span>
              <span>GPS DETECTED: Showing nearest Tamil Nadu restaurants based on your real-time location (Closest First)</span>
            </div>
            <button
              onClick={() => {
                handleFilterChange("user_lat", null);
                handleFilterChange("user_lng", null);
                handleFilterChange("sort_by", "rating");
              }}
              style={{
                backgroundColor: "#065F46",
                color: "#FFFFFF",
                border: "none",
                padding: "0.35rem 0.8rem",
                borderRadius: "var(--radius-full)",
                fontSize: "0.75rem",
                fontWeight: 800,
                cursor: "pointer"
              }}
            >
              Clear GPS Filter ├ù
            </button>
          </div>
        )}

        {/* Filter Bar */}
        <FilterBar
          filters={filters}
          onChange={handleFilterChange}
          onReset={handleResetFilters}
          cities={cities}
          cuisines={cuisines}
          totalCount={restaurants.length}
        />

        {/* Layout according to viewMode */}
        {viewMode === "split" ? (
          <div style={{
            display: "grid",
            gridTemplateColumns: "1.1fr 0.9fr",
            gap: "1.5rem",
            alignItems: "start"
          }}>
            {/* Left: Scrollable Restaurant Cards */}
            <div style={{ display: "flex", flexDirection: "column", gap: "1.25rem" }}>
              {loading ? (
                <div style={{ textAlign: "center", padding: "3rem", color: "var(--text-muted)" }}>
                  Updating search results...
                </div>
              ) : restaurants.length === 0 ? (
                <div style={{ textAlign: "center", padding: "3rem", backgroundColor: "var(--bg-card)", borderRadius: "var(--radius-xl)" }}>
                  <p style={{ fontWeight: 600, color: "var(--text-muted)" }}>No restaurants match your selected filters.</p>
                  <button onClick={handleResetFilters} className="btn btn-primary btn-sm" style={{ marginTop: "1rem" }}>
                    Reset Filters
                  </button>
                </div>
              ) : (
                restaurants.map((restaurant) => (
                  <RestaurantCard
                    key={restaurant.id}
                    restaurant={restaurant}
                    onSelect={(r) => { onSelectRestaurant(r); setSelectedMapRest(r); }}
                    onBook={onBookRestaurant}
                    onDirections={(r) => { onDirections(r); setSelectedMapRest(r); }}
                    isFavorite={favorites.has(restaurant.id)}
                    onToggleFavorite={handleToggleFav}
                  />
                ))
              )}
            </div>

            {/* Right: Sticky Interactive Map */}
            <div style={{ position: "sticky", top: "90px" }}>
              <InteractiveMap
                restaurants={restaurants}
                selectedRestaurant={selectedMapRest}
                onSelectRestaurant={(r) => setSelectedMapRest(r)}
              />
            </div>
          </div>
        ) : viewMode === "map" ? (
          <div style={{ height: "650px" }}>
            <InteractiveMap
              restaurants={restaurants}
              selectedRestaurant={selectedMapRest}
              onSelectRestaurant={(r) => setSelectedMapRest(r)}
            />
          </div>
        ) : (
          /* Grid View */
          <div>
            {loading ? (
              <div style={{ textAlign: "center", padding: "3rem", color: "var(--text-muted)" }}>
                Loading restaurants...
              </div>
            ) : restaurants.length === 0 ? (
              <div style={{ textAlign: "center", padding: "3rem", backgroundColor: "var(--bg-card)", borderRadius: "var(--radius-xl)" }}>
                <p style={{ fontWeight: 600, color: "var(--text-muted)" }}>No restaurants match your selected filters.</p>
                <button onClick={handleResetFilters} className="btn btn-primary btn-sm" style={{ marginTop: "1rem" }}>
                  Reset Filters
                </button>
              </div>
            ) : (
              <div className="grid-restaurants">
                {restaurants.map((restaurant) => (
                  <RestaurantCard
                    key={restaurant.id}
                    restaurant={restaurant}
                    onSelect={onSelectRestaurant}
                    onBook={onBookRestaurant}
                    onDirections={onDirections}
                    isFavorite={favorites.has(restaurant.id)}
                    onToggleFavorite={handleToggleFav}
                  />
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

const API_BASE_URL = "http://127.0.0.1:8000/api";
async function request(endpoint, options = {}) {
  const token = localStorage.getItem("srf_token");
  const headers = {
    "Content-Type": "application/json",
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
    ...options.headers,
  };

  const url = `${API_BASE_URL}${endpoint}`;
  try {
    const response = await fetch(url, { ...options, headers });

    if (response.status === 401) {
      // Unauthorized: could clear token if expired
    }

    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      const errorMsg = data?.detail || data?.message || "An unexpected error occurred.";
      throw new Error(typeof errorMsg === "string" ? errorMsg : JSON.stringify(errorMsg));
    }
    return data;
  } catch (err) {
    throw err;
  }
}

export const api = {
  // Auth
  login: (credentials) => request("/auth/login", { method: "POST", body: JSON.stringify(credentials) }),
  register: (userData) => request("/auth/register", { method: "POST", body: JSON.stringify(userData) }),
  getMe: () => request("/auth/me"),

  // Restaurants
  getRestaurants: (params = {}) => {
    const query = new URLSearchParams();
    Object.entries(params).forEach(([key, val]) => {
      if (val !== undefined && val !== null && val !== "" && val !== "all" && val !== "All") {
        query.append(key, val);
      }
    });
    const qs = query.toString();
    return request(`/restaurants${qs ? `?${qs}` : ""}`);
  },
  getCities: () => request("/restaurants/cities"),
  getCuisines: () => request("/restaurants/cuisines"),
  getRestaurantDetails: (id, coords) => {
    const qs = coords ? `?user_lat=${coords.lat}&user_lng=${coords.lng}` : "";
    return request(`/restaurants/${id}${qs}`);
  },
  updateRestaurantStatus: (id, statusData) =>
    request(`/restaurants/${id}/status`, { method: "PATCH", body: JSON.stringify(statusData) }),

  // Bookings
  createBooking: (bookingData) =>
    request("/bookings", { method: "POST", body: JSON.stringify(bookingData) }),
